def write_jsonl(path, rows):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows), encoding="utf-8", newline="\n")


def main():
    documents = ROOT / "data" / "documents"
    benchmark = ROOT / "data" / "benchmark"
    source = ROOT / "data" / "source"
    for directory in (documents, benchmark, source):
        directory.mkdir(parents=True, exist_ok=True)
    rng = random.Random(42)
    styles = getSampleStyleSheet()
    dev, test, facts = [], [], []
    for document_index, (policy, entries) in enumerate(POLICIES.items(), 1):
        filename = policy + ".pdf"
        dev_pages = set(rng.sample(range(1, len(entries) + 1), 3))
        story = []
        for page, (label, answer, question) in enumerate(entries, 1):
            section = f"{policy.upper()}-{page:02}"
            evidence = f"{label}: {answer}."
            if page > 1:
                story.append(PageBreak())
            for text, style in [
                ("Northstar Labs", "Title"),
                (policy.replace("_", " ").title(), "Heading1"),
                (section + " - " + label, "Heading2"),
                ("Fictional demonstration knowledge base. Version 1.0. This policy applies to employees and the Atlas product only where explicitly stated.", "BodyText"),
                (evidence, "Heading3"),
                (f"This section defines the rule for {label.lower()}. Employees should use this published rule when planning the activity described in this section. The policy owner is responsible for keeping the approved wording current. A request that falls outside the scope of this rule must be referred to the policy owner rather than interpreted as an automatic exception.", "BodyText"),
                ("Operational process: read the applicable section before submitting a request. Describe the business purpose, attach the supporting information, and route the request through the approved internal workflow. The reviewer checks whether the request is complete and whether it falls within the published policy. Keep the approval with the request so that the decision can be audited later.", "BodyText"),
                ("The procedural notes describe administration of this section. They do not create additional benefits, prices, service commitments, or technical limits. Different policies can use similar terminology while governing different activities. A rule from another document should not be substituted for this section without an explicit cross-reference. Employee-specific records, forecasts, future policy revisions and confidential credentials are outside the scope of this demonstration knowledge base.", "BodyText"),
            ]:
                story.append(Paragraph(text, styles[style]))
                story.append(Spacer(1, 12))
            sample = {"id": f"q{document_index:02}{page:02}", "question": question, "answer": answer, "answer_aliases": [answer], "answerable": True, "relevant_documents": [filename], "relevant_pages": [page], "relevant_sections": [section], "relevant_chunk_ids": [], "evidence_text": evidence}
            (dev if page in dev_pages else test).append(sample)
            facts.append({"filename": filename, "page": page, "section": section, "label": label, "answer": answer, "evidence_text": evidence})
        SimpleDocTemplate(str(documents / filename), pagesize=A4, invariant=1).build(story)
        negative_dev = rng.randrange(4)
        for index, question in enumerate(UNANSWERABLE[policy]):
            sample = {"id": f"u{document_index:02}{index + 1:02}", "question": question, "answer": None, "answerable": False, "relevant_documents": [], "relevant_pages": [], "relevant_chunk_ids": []}
            (dev if index == negative_dev else test).append(sample)
    rng.shuffle(dev)
    rng.shuffle(test)
    assert len({row["question"] for row in dev + test}) == 160
    write_jsonl(benchmark / "dev.jsonl", dev)
    write_jsonl(benchmark / "test.jsonl", test)
    write_jsonl(source / "facts.jsonl", facts)
    files = sorted(documents.glob("*.pdf")) + [benchmark / "dev.jsonl", benchmark / "test.jsonl", source / "facts.jsonl"]
    manifest = {"version": "northstar-v1", "seed": 42, "synthetic": True, "gold_provenance": "facts authored alongside fictional policies; no LLM-generated gold", "answerable": 120, "unanswerable": 40, "dev": {"answerable": 30, "unanswerable": 10}, "test": {"answerable": 90, "unanswerable": 30}, "files": {str(file.relative_to(ROOT)).replace('\\', '/'): hashlib.sha256(file.read_bytes()).hexdigest() for file in files}}
    (benchmark / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8", newline="\n")
    print(json.dumps({"documents": 10, "pages": 120, "dev": len(dev), "test": len(test), "manifest": str(benchmark / 'manifest.json')}))


if __name__ == "__main__":
    main()
